<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Maze Discovery — 24 Bots</title>
<style>
  html,body{
    margin:0; padding:0; height:100%;
    background:#14151f; color:#eee;
    font-family:"Segoe UI",Arial,sans-serif;
    display:flex; flex-direction:column; align-items:center;
  }
  h1{font-size:20px; margin:14px 0 6px 0; letter-spacing:.5px;}
  #hud{
    display:flex; gap:24px; align-items:center;
    background:#20222f; padding:8px 18px; border-radius:8px;
    margin-bottom:12px; font-size:15px;
  }
  #hud b{color:#7fd1ff;}
  #reset{
    background:#3d6ef0; color:white; border:none; border-radius:6px;
    padding:7px 16px; cursor:pointer; font-size:14px;
  }
  #reset:hover{background:#5a86ff;}
  #maze{
    border:3px solid #555; border-radius:6px; background:#0b0c12;
    box-shadow:0 0 18px rgba(0,0,0,.6);
  }
  canvas{display:block;}
  #seedinfo{font-size:12px; color:#888; margin-top:8px;}
</style>
</head>
<body>
  <h1>Maze Discovery — 24 Autonomous Bots</h1>
  <div id="hud">
    <div>Completed: <b id="completed">0</b> / 24</div>
    <div>Timer: <b id="timer">0.0s</b></div>
    <button id="reset">Reset</button>
  </div>
  <div id="maze">
    <canvas id="canvas"></canvas>
  </div>
  <div id="seedinfo">seed: <span id="seedval">-</span></div>

<script>
(function(){
  "use strict";

  // ---------- PRNG ----------
  function mulberry32(a){
    a = a >>> 0;
    return function(){
      a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function shuffle(arr, rng){
    const a = arr.slice();
    for(let i=a.length-1;i>0;i--){
      const j = Math.floor(rng()*(i+1));
      const tmp=a[i]; a[i]=a[j]; a[j]=tmp;
    }
    return a;
  }
  function permutations(arr){
    if(arr.length<=1) return [arr.slice()];
    const res=[];
    for(let i=0;i<arr.length;i++){
      const rest = arr.slice(0,i).concat(arr.slice(i+1));
      for(const p of permutations(rest)){
        res.push([arr[i]].concat(p));
      }
    }
    return res;
  }

  // ---------- constants ----------
  const ROWS = 21, COLS = 21;
  const CELL = 20;
  const DIRS = ['n','e','s','w'];
  const DELTA = { n:{dr:-1,dc:0}, s:{dr:1,dc:0}, e:{dr:0,dc:1}, w:{dr:0,dc:-1} };
  const OPP = { n:'s', s:'n', e:'w', w:'e' };
  const TICK_MS = 130;
  const NUM_BOTS = 24;

  // ---------- state ----------
  let rng, maze, spawn, exit, bots;
  let finishedCount, tickCount, elapsed, currentSeed;
  let lastTickTime = performance.now();
  let autoPlay = true;
  let autoHandle = null;

  // ---------- maze generation ----------
  function generateMaze(rows, cols, rng){
    const cells = [];
    for(let r=0;r<rows;r++){
      const row=[];
      for(let c=0;c<cols;c++){
        row.push({r,c,n:true,e:true,s:true,w:true,visited:false});
      }
      cells.push(row);
    }
    const stack = [cells[0][0]];
    cells[0][0].visited = true;
    while(stack.length){
      const cur = stack[stack.length-1];
      const order = shuffle(DIRS, rng);
      let advanced = false;
      for(const dir of order){
        const d = DELTA[dir];
        const nr = cur.r+d.dr, nc = cur.c+d.dc;
        if(nr<0||nr>=rows||nc<0||nc>=cols) continue;
        const nb = cells[nr][nc];
        if(nb.visited) continue;
        cur[dir]=false;
        nb[OPP[dir]]=false;
        nb.visited=true;
        stack.push(nb);
        advanced = true;
        break;
      }
      if(!advanced) stack.pop();
    }
    return cells;
  }

  function bfsFarthest(cells, rows, cols, start){
    const dist = [];
    for(let r=0;r<rows;r++) dist.push(new Array(cols).fill(-1));
    dist[start.r][start.c] = 0;
    const q = [start];
    let qi = 0;
    let far = start;
    while(qi < q.length){
      const cur = q[qi++];
      const cell = cells[cur.r][cur.c];
      for(const dir of DIRS){
        if(cell[dir]) continue;
        const d = DELTA[dir];
        const nr = cur.r+d.dr, nc = cur.c+d.dc;
        if(dist[nr][nc] === -1){
          dist[nr][nc] = dist[cur.r][cur.c] + 1;
          q.push({r:nr,c:nc});
          if(dist[nr][nc] > dist[far.r][far.c]) far = {r:nr,c:nc};
        }
      }
    }
    return far;
  }

  function keyOf(cell){ return cell.r + ',' + cell.c; }
  function neighborCell(cell, dir){
    const d = DELTA[dir];
    const nr = cell.r + d.dr, nc = cell.c + d.dc;
    if(nr<0||nr>=ROWS||nc<0||nc>=COLS) return null;
    return {r:nr, c:nc};
  }

  // ---------- bots ----------
  function initBots(spawn, rng){
    const perms = shuffle(permutations(DIRS), rng);
    const arr = [];
    for(let i=0;i<NUM_BOTS;i++){
      arr.push({
        id: i,
        color: 'hsl(' + Math.round(i*360/NUM_BOTS) + ',75%,60%)',
        dirPref: perms[i % perms.length],
        pos: {r:spawn.r, c:spawn.c},
        prevPos: {r:spawn.r, c:spawn.c},
        stack: [{r:spawn.r, c:spawn.c}],
        visited: new Set([keyOf(spawn)]),
        deadSet: new Set(),
        deadEnds: [],
        path: [{r:spawn.r, c:spawn.c}],
        finished: false,
        finishTick: null
      });
    }
    return arr;
  }

  function stepBot(bot){
    if(bot.finished) return;
    const cur = bot.pos;
    const cell = maze[cur.r][cur.c];
    let moved = false;
    for(const dir of bot.dirPref){
      if(cell[dir]) continue; // wall present -> blocked
      const nb = neighborCell(cur, dir);
      if(!nb) continue;
      const nk = keyOf(nb);
      if(bot.visited.has(nk)) continue; // already explored branch
      bot.visited.add(nk);
      bot.stack.push(nb);
      bot.prevPos = cur;
      bot.pos = nb;
      bot.path.push({r:nb.r, c:nb.c});
      moved = true;
      break;
    }
    if(!moved){
      const key = keyOf(cur);
      if(!bot.deadSet.has(key)){
        bot.deadSet.add(key);
        bot.deadEnds.push({r:cur.r, c:cur.c});
      }
      if(bot.stack.length > 1){
        bot.stack.pop();
        const parent = bot.stack[bot.stack.length-1];
        bot.prevPos = cur;
        bot.pos = parent;
        bot.path.push({r:parent.r, c:parent.c});
      }
      // else: fully stuck at root (should not happen on a perfect maze
      // before the exit has been found), bot simply waits.
    }
    if(!bot.finished && bot.pos.r === exit.r && bot.pos.c === exit.c){
      bot.finished = true;
      bot.finishTick = tickCount;
      finishedCount++;
    }
  }

  function doTick(){
    if(finishedCount >= bots.length) return;
    tickCount++;
    for(const b of bots) stepBot(b);
    elapsed = tickCount;
  }

  // ---------- rendering ----------
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = COLS * CELL;
  canvas.height = ROWS * CELL;

  function drawMaze(){
    ctx.fillStyle = '#0b0c12';
    ctx.fillRect(0,0,canvas.width, canvas.height);
    ctx.strokeStyle = '#c8ccd8';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for(let r=0;r<ROWS;r++){
      for(let c=0;c<COLS;c++){
        const cell = maze[r][c];
        const x = c*CELL, y = r*CELL;
        if(cell.n){ ctx.moveTo(x,y); ctx.lineTo(x+CELL,y); }
        if(cell.w){ ctx.moveTo(x,y); ctx.lineTo(x,y+CELL); }
        if(cell.s){ ctx.moveTo(x,y+CELL); ctx.lineTo(x+CELL,y+CELL); }
        if(cell.e){ ctx.moveTo(x+CELL,y); ctx.lineTo(x+CELL,y+CELL); }
      }
    }
    ctx.stroke();

    // spawn marker
    ctx.fillStyle = '#3498db';
    ctx.fillRect(spawn.c*CELL+CELL*0.32, spawn.r*CELL+CELL*0.32, CELL*0.36, CELL*0.36);

    // exit marker
    ctx.fillStyle = '#2ecc71';
    ctx.beginPath();
    ctx.arc(exit.c*CELL+CELL/2, exit.r*CELL+CELL/2, CELL*0.32, 0, Math.PI*2);
    ctx.fill();
  }

  function drawBots(){
    const now = performance.now();
    const frac = Math.max(0, Math.min(1, (now - lastTickTime) / TICK_MS));
    for(const b of bots){
      const pr = b.prevPos.r, pc = b.prevPos.c;
      const cr = b.pos.r, cc = b.pos.c;
      const x = (pc + (cc-pc)*frac + 0.5) * CELL;
      const y = (pr + (cr-pr)*frac + 0.5) * CELL;
      ctx.beginPath();
      ctx.fillStyle = b.color;
      ctx.arc(x, y, CELL*0.26, 0, Math.PI*2);
      ctx.fill();
      if(b.finished){
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = '#fff';
        ctx.stroke();
      }
    }
  }

  function render(){
    drawMaze();
    drawBots();
  }

  function updateHUD(){
    document.getElementById('completed').textContent = finishedCount;
    document.getElementById('timer').textContent = (elapsed*TICK_MS/1000).toFixed(1) + 's';
    document.getElementById('seedval').textContent = currentSeed;
  }

  // ---------- reset / setup ----------
  function resetGame(seed){
    currentSeed = (seed===undefined || seed===null || seed==='') ?
      ((Date.now() ^ Math.floor(Math.random()*0xFFFFFFFF)) >>> 0) : (Number(seed) >>> 0);
    rng = mulberry32(currentSeed);
    maze = generateMaze(ROWS, COLS, rng);
    spawn = {r:0, c:0};
    exit = bfsFarthest(maze, ROWS, COLS, spawn);
    bots = initBots(spawn, rng);
    finishedCount = 0;
    tickCount = 0;
    elapsed = 0;
    lastTickTime = performance.now();
  }

  function startAuto(){
    if(autoHandle) clearInterval(autoHandle);
    autoHandle = setInterval(function(){
      if(!autoPlay) return;
      if(finishedCount < bots.length){
        doTick();
        lastTickTime = performance.now();
        updateHUD();
      }
    }, TICK_MS);
  }

  // ---------- animation loop ----------
  function animLoop(){
    render();
    requestAnimationFrame(animLoop);
  }

  // ---------- public API ----------
  window.game = {
    tick: function(n){
      autoPlay = false; // external script takes control
      n = (n===undefined) ? 1 : n;
      for(let i=0;i<n;i++) doTick();
      lastTickTime = performance.now();
      render();
      updateHUD();
    },
    reset: function(seed){
      resetGame(seed);
      autoPlay = true;
      render();
      updateHUD();
    },
    get elapsed(){ return elapsed; },
    get size(){ return {rows: ROWS, cols: COLS}; },
    get spawn(){ return {r: spawn.r, c: spawn.c}; },
    get exit(){ return {r: exit.r, c: exit.c}; },
    walls: function(r,c){
      const cell = maze[r][c];
      return {n: cell.n, e: cell.e, s: cell.s, w: cell.w};
    },
    get bots(){ return bots; }
  };

  // ---------- wiring ----------
  document.getElementById('reset').addEventListener('click', function(){
    window.game.reset();
  });

  // initial boot
  resetGame(undefined);
  updateHUD();
  startAuto();
  requestAnimationFrame(animLoop);

})();
</script>
</body>
</html>
